param([string]$Server,[string]$InputFile,[string]$Query,[string]$Database='master',[switch]$UseSqlAuth,[string]$User,[string]$Password); if(-not(Get-Command sqlcmd -ErrorAction SilentlyContinue)){throw 'sqlcmd.exe not found'};$auth=$UseSqlAuth? @('-U',$User,'-P',$Password):@('-E');$common=@('-S',$Server,'-d',$Database,'-b','-r1')+$auth;if($InputFile){& sqlcmd @common -i $InputFile}elseif($Query){& sqlcmd @common -Q $Query}else{throw 'Provide -InputFile or -Query'};if($LASTEXITCODE -ne 0){throw "sqlcmd exit $LASTEXITCODE"}
